package cn.roomguard;
import android.app.*;import android.os.*;import android.content.*;import android.graphics.Color;import android.net.Uri;import android.view.*;import android.webkit.*;import android.widget.*;
public class MainActivity extends Activity {
 WebView web;String base;LinearLayout root;
 @Override public void onCreate(Bundle b){super.onCreate(b);base=getSharedPreferences("rg",0).getString("server","http://192.168.1.103:8080");root=new LinearLayout(this);root.setOrientation(1);root.setBackgroundColor(Color.WHITE);LinearLayout bar=new LinearLayout(this);Button settings=new Button(this);settings.setText("服务器／后台告警");Button reload=new Button(this);reload.setText("刷新");Button provision=new Button(this);provision.setText("节点配网");provision.setOnClickListener(v->new AlertDialog.Builder(this).setTitle("配置ESP节点").setMessage("先连接ESP配置热点并保持无互联网连接，再用系统浏览器打开192.168.4.1。完成后切回比赛Wi-Fi，请教师批准接入。").setPositiveButton("Wi-Fi设置",(d,w)->startActivity(new Intent(android.provider.Settings.ACTION_WIFI_SETTINGS))).setNeutralButton("打开配网页",(d,w)->startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse("http://192.168.4.1")))).setNegativeButton("取消",null).show());bar.addView(settings);bar.addView(reload);bar.addView(provision);root.addView(bar);web=new WebView(this);root.addView(web,new LinearLayout.LayoutParams(-1,0,1));setContentView(root);
 web.getSettings().setJavaScriptEnabled(true);web.getSettings().setDomStorageEnabled(true);web.getSettings().setAllowFileAccess(false);web.getSettings().setAllowContentAccess(false);web.getSettings().setBuiltInZoomControls(false);web.setWebChromeClient(new WebChromeClient());web.setWebViewClient(new WebViewClient(){@Override public boolean shouldOverrideUrlLoading(WebView v,String url){if(sameOrigin(url)){return false;}Toast.makeText(MainActivity.this,"仅允许访问已配置服务器",Toast.LENGTH_SHORT).show();return true;}});web.addJavascriptInterface(new Object(){@JavascriptInterface public String getTerminalId(){return TerminalIdentity.get(MainActivity.this);}@JavascriptInterface public void saveCsv(String data){if(data==null||data.length()>10000000)return;try{java.io.File f=new java.io.File(getExternalFilesDir(null),"RoomGuard-"+System.currentTimeMillis()+".csv");java.io.FileOutputStream stream=new java.io.FileOutputStream(f);stream.write(data.getBytes("UTF-8"));stream.close();runOnUiThread(()->new AlertDialog.Builder(MainActivity.this).setMessage("CSV已保存："+f.getAbsolutePath()).setPositiveButton("确定",null).show());}catch(Exception ex){runOnUiThread(()->Toast.makeText(MainActivity.this,"保存失败",Toast.LENGTH_LONG).show());}}},"AndroidExport");
 web.setDownloadListener((url,agent,disp,mime,len)->new AlertDialog.Builder(this).setMessage("CSV请在局域网电脑或手机浏览器管理端登录后导出。").setPositiveButton("确定",null).show());web.loadUrl(base+"/");settings.setOnClickListener(v->configure());reload.setOnClickListener(v->web.reload());if(getSharedPreferences("rg",0).getBoolean("background",false))startAlerts(); }
 boolean sameOrigin(String url){try{Uri a=Uri.parse(url),b=Uri.parse(base);return a.getScheme().equals(b.getScheme())&&a.getHost().equals(b.getHost())&&a.getPort()==b.getPort();}catch(Exception e){return false;}}
 void startAlerts(){Intent i=new Intent(this,AlertService.class);if(Build.VERSION.SDK_INT>=26)startForegroundService(i);else startService(i);}
 void configure(){LinearLayout l=new LinearLayout(this);l.setPadding(35,20,35,20);l.setOrientation(1);EditText address=new EditText(this);address.setSingleLine(true);address.setText(base);l.addView(address);CheckBox bg=new CheckBox(this);bg.setText("启用后台／锁屏告警（显示常驻通知）");bg.setChecked(getSharedPreferences("rg",0).getBoolean("background",false));l.addView(bg);TextView tip=new TextView(this);tip.setText("请允许自启动及后台运行，关闭本应用省电限制，保持锁屏Wi-Fi连接。必须与树莓派网络可达；网页声音建议关闭以免重复。切换服务器会重启后台连接。");l.addView(tip);new AlertDialog.Builder(this).setTitle("连接设置").setView(l).setPositiveButton("保存",(d,w)->{String value=address.getText().toString().trim().replaceAll("/+$","");if(!value.matches("https?://[A-Za-z0-9.\\-]+(:[0-9]{1,5})?")){Toast.makeText(this,"地址格式错误",Toast.LENGTH_LONG).show();return;}base=value;getSharedPreferences("rg",0).edit().putString("server",base).putBoolean("background",bg.isChecked()).apply();stopService(new Intent(this,AlertService.class));if(bg.isChecked())startAlerts();web.loadUrl(base+"/");}).setNegativeButton("取消",null).show();}
 @Override public void onBackPressed(){if(web.canGoBack())web.goBack();else super.onBackPressed();}
 @Override public void onDestroy(){web.destroy();super.onDestroy();}
}
